    task_group, by_id, dependents = _build_task_group_and_dependents(groups)
    out: set[str] = set(failing)
    _traverse_downstream(failing, task_group, by_id, dependents, out)
    return out


def _build_task_group_and_dependents(groups: list[WorkGroup]) -> tuple[dict[str, str], dict[str, WorkGroup], dict[str, list[str]]]:
    task_group: dict[str, str] = {}
    by_id = {g.id: g for g in groups}
    dependents: dict[str, list[str]] = {g.id: [] for g in groups}
    for g in groups:
        for t in g.tasks:
            task_group[t.id] = g.id
        for d in g.depends_on:
            if d in dependents:
                dependents[d].append(g.id)
    return task_group, by_id, dependents


def _traverse_downstream(
    failing: set[str],
    task_group: dict[str, str],
    by_id: dict[str, WorkGroup],
    dependents: dict[str, list[str]],
    out: set[str],
) -> None:
    stack = [task_group[t] for t in failing if t in task_group]
    seen: set[str] = set()
    while stack:
        gid = stack.pop()
        if gid in seen:
            continue
        seen.add(gid)
        for dep in dependents[gid]:
            for t in by_id[dep].tasks:
                out.add(t.id)
            stack.append(dep)"}

